import{_ as s,o as a,c as i,ag as n}from"./chunks/framework.DXGyWiRo.js";const k=JSON.parse('{"title":"Java基础","description":"","frontmatter":{},"headers":[],"relativePath":"interviews/java/base.md","filePath":"interviews/java/base.md","lastUpdated":1756779477000}'),r={name:"interviews/java/base.md"};function d(e,t,l,h,o,g){return a(),i("div",null,[...t[0]||(t[0]=[n('<h1 id="java基础" tabindex="-1"><code>Java</code>基础 <a class="header-anchor" href="#java基础" aria-label="Permalink to &quot;`Java`基础&quot;">​</a></h1><h2 id="抽象类和接口的区别是什么" tabindex="-1">抽象类和接口的区别是什么? <a class="header-anchor" href="#抽象类和接口的区别是什么" aria-label="Permalink to &quot;抽象类和接口的区别是什么?&quot;">​</a></h2><table tabindex="0"><thead><tr><th><strong>异同点</strong></th><th><strong>接口</strong></th><th><strong>抽象类</strong></th></tr></thead><tbody><tr><td><strong>与类的关系</strong></td><td>(多)实现</td><td>(单)继承</td></tr><tr><td><strong>成员变量</strong></td><td>静态常量(类常量)</td><td>[实例/静态][变量/常量]</td></tr><tr><td><strong>抽象方法</strong></td><td>有</td><td></td></tr><tr><td><strong>构造方法</strong></td><td>无</td><td>有</td></tr><tr><td><strong>实例化</strong></td><td>不能直接实例化, 必须被实现接口或继承抽象类</td><td></td></tr><tr><td><strong>继承</strong></td><td>多继承</td><td>单继承</td></tr><tr><td><strong>设计目的</strong></td><td>约束类的行为</td><td>代码复用,强调所属关系</td></tr></tbody></table><h2 id="和equals的区别是什么" tabindex="-1"><code>==</code>和<code>equals</code>的区别是什么? <a class="header-anchor" href="#和equals的区别是什么" aria-label="Permalink to &quot;`==`和`equals`的区别是什么?&quot;">​</a></h2><table tabindex="0"><thead><tr><th><strong>对比项</strong></th><th><strong>==</strong></th><th><strong>equals</strong></th></tr></thead><tbody><tr><td><strong>基本类型</strong></td><td>比较值</td><td>不支持</td></tr><tr><td><strong>引用类型</strong></td><td>比较内存地址</td><td>未重写时采用==比较<br><br>重写后比较对象的内容</td></tr></tbody></table><h2 id="字符串常量方式创建和new方式创建有什么区别" tabindex="-1">字符串常量方式创建和<code>new</code>方式创建有什么区别? <a class="header-anchor" href="#字符串常量方式创建和new方式创建有什么区别" aria-label="Permalink to &quot;字符串常量方式创建和`new`方式创建有什么区别?&quot;">​</a></h2><p><strong>字符串常量方式创建:</strong></p><p>查找常量池中是否存在该字符串对象</p><p>a. 如果存在直接复用常量池中的字符串对象</p><p>b. 如果不存在则在常量池中新建该字符串对象</p><p><strong>字符串new方式创建:</strong></p><p>查找常量池中是否存在该字符串对象</p><p>a. 如果存在则不会在常量池中创建该字符串对象</p><p>b. 如果不存在则在常量池中创建该字符串对象，并且在堆中创建该字符串对象，返回堆中字符串对象的引用。</p><p>简答: 如果字符串常量池中不存在该字符串对象，首先会在常量池中创建该字符串对象，然后会在堆中创建该字符串对象</p><table tabindex="0"><thead><tr><th><strong>异同点</strong></th><th><strong>常量方式创建</strong></th><th><strong>new方式创建</strong></th></tr></thead><tbody><tr><td><strong>内存位置</strong></td><td>字符串常量池</td><td>堆</td></tr><tr><td><strong>行为</strong></td><td>有则复用，无则新建</td><td>每次新建</td></tr><tr><td><strong>常量池</strong></td><td>总是使用</td><td>可能触发常量池创建</td></tr><tr><td><strong>对象复用</strong></td><td>复用</td><td>不复用，每次新建</td></tr><tr><td><strong>内存占用</strong></td><td>节省内存</td><td>内存开销大</td></tr></tbody></table><h2 id="string、stringbuilder和stringbuffer有什么区别" tabindex="-1"><code>String</code>、<code>StringBuilder</code>和<code>StringBuffer</code>有什么区别？ <a class="header-anchor" href="#string、stringbuilder和stringbuffer有什么区别" aria-label="Permalink to &quot;`String`、`StringBuilder`和`StringBuffer`有什么区别？&quot;">​</a></h2><table tabindex="0"><thead><tr><th><strong>异同点</strong></th><th><strong>String</strong></th><th><strong>StringBuffer</strong></th><th><strong>StringBuilder</strong></th></tr></thead><tbody><tr><td><strong>线程安全</strong></td><td>安全，常量</td><td>安全，synchronized</td><td>非安全</td></tr><tr><td><strong>性能</strong></td><td>较低</td><td>中等</td><td>高效</td></tr><tr><td><strong>父类</strong></td><td>Object</td><td>AbstractStringBuilder</td><td></td></tr><tr><td><strong>可变性</strong></td><td>不可变</td><td>可变</td><td></td></tr><tr><td><strong>适用场景</strong></td><td>修改、拼接较少</td><td>多线程修改、拼接</td><td>单线程修改、拼接</td></tr></tbody></table><h2 id="为什么stringbuilder的拼接效率高" tabindex="-1">为什么<code>StringBuilder</code>的拼接效率高? <a class="header-anchor" href="#为什么stringbuilder的拼接效率高" aria-label="Permalink to &quot;为什么`StringBuilder`的拼接效率高?&quot;">​</a></h2><ol><li>String没有拼接能力, String的+拼接底层采用SB.append方法完成拼接, 还需要toSTring转为SB字符串才行, 频繁地向堆中申请空间, 造成资源浪费, 耗时比较久</li><li>StringBuilder自始至终 持有一个StringBuilder对象, 运行效率高, 运行速度快</li></ol><h2 id="为什么string类是不可变的" tabindex="-1">为什么<code>String</code>类是不可变的? <a class="header-anchor" href="#为什么string类是不可变的" aria-label="Permalink to &quot;为什么`String`类是不可变的?&quot;">​</a></h2><ol><li>保存字符串的数组被<code>private final</code>修饰, 并且未提供/暴露修改这个数组的方法</li><li>String类被final修饰, 使其不能有子类, 避免子类修改String</li></ol><p>注意: jdk9之前, 底层是<code>char[]</code>, jdk9+, 底层是<code>byte[]</code></p><h2 id="string类的常用方法有哪些" tabindex="-1"><code>String</code>类的常用方法有哪些? <a class="header-anchor" href="#string类的常用方法有哪些" aria-label="Permalink to &quot;`String`类的常用方法有哪些?&quot;">​</a></h2><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() 构造方法</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">length</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() 获取长度</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">charAt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() 获取指定位置的字符</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">indexOf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() 获取字符(串)首次出现的位置</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lastIndexOf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() 获取字符(串)末次出现的位置</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">substring</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() 获取子串, 左闭右开区间</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">split</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() 拆分字符串</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">trim</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() 去除字符串两端的空白字符</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">contains</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() 判断是否包含指定字符序列</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">replace</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() 替换字符(串)</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getBytes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() 获取字节数组</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">equals</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() 判断字符串是否相等</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">equalsIgnoreCase</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() 判断字符串相等(忽略大小写)</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">startsWith</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() 判断字符串开头</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">endsWith</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() 判断字符串结尾</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toLowerCase</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() 转成小写</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toUpperCase</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() 转成大写</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ValueOf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() 数字转字符串</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">isBlank</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() 判空</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">isEmpty</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() 判空</span></span></code></pre></div><h2 id="重载-overload-和重写-override-有什么区别" tabindex="-1">重载(<code>overload</code>)和重写(<code>override</code>)有什么区别? <a class="header-anchor" href="#重载-overload-和重写-override-有什么区别" aria-label="Permalink to &quot;重载(`overload`)和重写(`override`)有什么区别?&quot;">​</a></h2><table tabindex="0"><thead><tr><th><strong>异同点</strong></th><th><strong>重载</strong></th><th><strong>重写</strong></th></tr></thead><tbody><tr><td><strong>发生范围</strong></td><td>同一个类</td><td>子类</td></tr><tr><td><strong>方法名</strong></td><td>相同</td><td>相同</td></tr><tr><td><strong>参数列表</strong></td><td>不相同</td><td>相同</td></tr><tr><td><strong>访问权限</strong></td><td>无限制</td><td>&gt;=父类</td></tr><tr><td><strong>返回值类型</strong></td><td>无限制</td><td>基本类型=父类<br>引用类型&lt;=父类</td></tr><tr><td><strong>异常类型</strong></td><td>无限制</td><td>&lt;=父类</td></tr><tr><td><strong>发生阶段</strong></td><td>编译期</td><td>运行期</td></tr><tr><td><strong>静态方法</strong></td><td>可以重载</td><td>不能重写(可以被继承)</td></tr><tr><td><strong>final方法</strong></td><td>可以重载</td><td>不能重写(可以被继承)</td></tr><tr><td><strong>构造方法</strong></td><td>可以重载</td><td>不能重写(不能被继承)</td></tr></tbody></table><h2 id="泛型有什么优势-泛型有什么局限" tabindex="-1">泛型有什么优势?泛型有什么局限? <a class="header-anchor" href="#泛型有什么优势-泛型有什么局限" aria-label="Permalink to &quot;泛型有什么优势?泛型有什么局限?&quot;">​</a></h2><h2 id="异常有哪些分类" tabindex="-1">异常有哪些分类? <a class="header-anchor" href="#异常有哪些分类" aria-label="Permalink to &quot;异常有哪些分类?&quot;">​</a></h2><h2 id="怎么处理异常" tabindex="-1">怎么处理异常? <a class="header-anchor" href="#怎么处理异常" aria-label="Permalink to &quot;怎么处理异常?&quot;">​</a></h2><h2 id="final关键字的作用是什么" tabindex="-1">final关键字的作用是什么? <a class="header-anchor" href="#final关键字的作用是什么" aria-label="Permalink to &quot;final关键字的作用是什么?&quot;">​</a></h2><p>[[jvm]]</p>',32)])])}const c=s(r,[["render",d]]);export{k as __pageData,c as default};
